const I18N={en:{home:'Home',products:'Products',factory:'Factory',contact:'Contact',quote:'Get a quote',tag:'Your trusted mountain bike supply partner',cookie:'We use essential cookies to improve site operation and measurement.',accept:'Accept',whatsapp:'WhatsApp chat',all:'All bikes',trail:'Trail / All-mountain',hardtail:'Hardtail',electric:'E-MTB',inquiry:'Send inquiry',language:'Language'},es:{home:'Inicio',products:'Productos',factory:'Fábrica',contact:'Contacto',quote:'Solicitar presupuesto',tag:'Su socio de confianza en suministro de bicicletas de montaña',cookie:'Usamos cookies esenciales para mejorar el funcionamiento y la medición del sitio.',accept:'Aceptar',whatsapp:'Chat por WhatsApp',all:'Todas las bicicletas',trail:'Trail / All-mountain',hardtail:'Rígida',electric:'E-MTB',inquiry:'Enviar consulta',language:'Idioma'},zh:{home:'首页',products:'产品展示',factory:'工厂实力',contact:'联系我们',quote:'获取报价',tag:'您信赖的山地车供应伙伴',cookie:'我们使用必要的 Cookie 来改善网站运行和数据衡量。',accept:'同意',whatsapp:'WhatsApp 在线咨询',all:'全部车型',trail:'林道 / 全山地',hardtail:'硬尾山地车',electric:'电助力山地车',inquiry:'提交询盘',language:'语言'},ru:{home:'Главная',products:'Продукция',factory:'Производство',contact:'Контакты',quote:'Получить предложение',tag:'Ваш надежный партнер по поставкам горных велосипедов',cookie:'Мы используем необходимые cookie для работы и анализа сайта.',accept:'Принять',whatsapp:'Чат в WhatsApp',all:'Все велосипеды',trail:'Трейл / All-mountain',hardtail:'Хардтейл',electric:'Электро-MTB',inquiry:'Отправить запрос',language:'Язык'},ar:{home:'الرئيسية',products:'المنتجات',factory:'المصنع',contact:'اتصل بنا',quote:'اطلب عرض سعر',tag:'شريكك الموثوق لتوريد الدراجات الجبلية',cookie:'نستخدم ملفات تعريف الارتباط الأساسية لتحسين عمل الموقع وقياسه.',accept:'موافقة',whatsapp:'محادثة واتساب',all:'كل الدراجات',trail:'تريل / جبال',hardtail:'هاردتيل',electric:'دراجات كهربائية',inquiry:'إرسال الاستفسار',language:'اللغة'}};
const products=[
 {id:'SF-29T',name:'Summit Trail 29',type:'trail',wheel:'29 in',frame:'6061 Alloy / 140 mm',groupset:'1×12 drivetrain',moq:'100 units'},
 {id:'SF-XC',name:'Crossline XC Pro',type:'hardtail',wheel:'29 in',frame:'Carbon / 100 mm',groupset:'1×12 drivetrain',moq:'80 units'},
 {id:'SF-E750',name:'Range E-750',type:'electric',wheel:'29 in',frame:'Alloy / 150 mm',groupset:'750 Wh / 85 Nm',moq:'60 units'},
 {id:'SF-27',name:'Ridge 27.5',type:'hardtail',wheel:'27.5 in',frame:'6061 Alloy / 120 mm',groupset:'1×10 drivetrain',moq:'120 units'},
 {id:'SF-EN',name:'Enduro Forge',type:'trail',wheel:'29 in',frame:'Carbon / 160 mm',groupset:'1×12 drivetrain',moq:'70 units'},
 {id:'SF-E500',name:'Metro Trail E-500',type:'electric',wheel:'27.5 in',frame:'Alloy / 130 mm',groupset:'500 Wh / 70 Nm',moq:'80 units'}
];
function getLang(){return localStorage.getItem('sf-lang')||'en'}function t(k){return(I18N[getLang()]||I18N.en)[k]||k}
function setLang(l){localStorage.setItem('sf-lang',l);document.documentElement.lang=l;document.body.classList.toggle('rtl',l==='ar');document.querySelectorAll('[data-t]').forEach(n=>n.textContent=t(n.dataset.t));document.querySelectorAll('[data-tph]').forEach(n=>n.placeholder=t(n.dataset.tph));const s=document.querySelector('#language');if(s)s.value=l}
function header(active){return `<div class="topline"><div class="shell"><span>OEM / ODM mountain bikes · Global B2B supply</span><span>Reply within 12 hours</span></div></div><header class="site-header"><div class="shell header-inner"><a class="brand" href="index.html"><span class="brand-mark">▲</span>VELO<b>AXIS</b></a><button class="menu" aria-label="Open navigation" id="menu">☰</button><nav class="nav" id="nav"><a class="${active==='home'?'active':''}" href="index.html" data-t="home">Home</a><a class="${active==='products'?'active':''}" href="products.html" data-t="products">Products</a><a class="${active==='factory'?'active':''}" href="factory.html" data-t="factory">Factory</a><a class="${active==='contact'?'active':''}" href="contact.html" data-t="contact">Contact</a></nav><div class="head-tools"><select id="language" class="lang" aria-label="Language"><option value="en">English</option><option value="es">Español</option><option value="zh">中文</option><option value="ru">Русский</option><option value="ar">العربية</option></select><a class="btn" href="contact.html#quote" data-t="quote">Get a quote</a></div></div></header>`}
function footer(){return `<footer class="site-footer"><div class="shell"><div class="footer-grid"><div><a class="brand" href="index.html"><span class="brand-mark">▲</span>VELO<b>AXIS</b></a><p>OEM and export-ready mountain bikes built for specialist distributors, retail programs and adventure brands.</p></div><div><h4>Collection</h4><a href="products.html?type=trail">Trail & All-mountain</a><a href="products.html?type=hardtail">Hardtail</a><a href="products.html?type=electric">E-MTB</a></div><div><h4>Trade support</h4><a href="factory.html#oem">OEM / ODM capability</a><a href="factory.html#quality">Quality control</a><a href="contact.html#quote">Request samples</a></div><div><h4>Contact</h4><a href="mailto:sales@veloaxis.example">sales@veloaxis.example</a><a href="https://wa.me/?text=Hello%20VeloAxis%2C%20I%20would%20like%20to%20request%20a%20quotation." target="_blank">WhatsApp enquiry ↗</a><a href="admin.html">Management portal</a></div></div><div class="footer-bottom"><span>© 2026 VeloAxis. B2B export catalogue.</span><span><a href="privacy.html">Privacy policy</a> · Cookie preferences</span></div></div></footer><a class="wa-float" href="https://wa.me/?text=Hello%20VeloAxis%2C%20I%20would%20like%20to%20discuss%20mountain%20bike%20supply." target="_blank" aria-label="Open WhatsApp"><b>◉</b><span data-t="whatsapp">WhatsApp chat</span></a>`}
function productCard(p){return `<article class="product-card" data-type="${p.type}"><div class="product-visual"><span class="tag">${p.type}</span><span class="bike-frame"></span></div><div class="product-info"><span class="tag">${p.id}</span><h3>${p.name}</h3><ul class="specs"><li><b>Wheel:</b> ${p.wheel}</li><li><b>Frame:</b> ${p.frame}</li><li><b>Spec:</b> ${p.groupset}</li><li><b>MOQ:</b> ${p.moq}</li></ul><a class="btn outline" href="contact.html?model=${encodeURIComponent(p.name)}#quote" data-t="inquiry">Send inquiry</a></div></article>`}
function renderProducts(filter='all'){const el=document.querySelector('#product-grid');if(!el)return;el.innerHTML=products.filter(p=>filter==='all'||p.type===filter).map(productCard).join('')}
function bindProducts(){const par=new URLSearchParams(location.search);let current=par.get('type')||'all';renderProducts(current);document.querySelectorAll('.filter').forEach(b=>{if(b.dataset.filter===current)b.classList.add('active');b.onclick=()=>{current=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));renderProducts(current)}})}
function bindForm(){const form=document.querySelector('#quote-form');if(!form)return;const model=new URLSearchParams(location.search).get('model');if(model&&form.querySelector('[name=model]'))form.querySelector('[name=model]').value=model;form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));const list=JSON.parse(localStorage.getItem('sf-enquiries')||'[]');list.unshift({...data,at:new Date().toLocaleString()});localStorage.setItem('sf-enquiries',JSON.stringify(list));form.innerHTML='<h3>Thank you — your enquiry is received.</h3><p>Our export team will reply within 12 hours. For an immediate conversation, please use WhatsApp.</p><a class="btn orange" target="_blank" href="https://wa.me/?text=Hello%20VeloAxis%2C%20I%20just%20sent%20an%20enquiry.">Open WhatsApp</a>'}}
function initCookie(){if(localStorage.getItem('sf-cookie'))return;const n=document.createElement('aside');n.className='cookie';n.innerHTML=`<b>Cookie notice</b><p data-t="cookie">${t('cookie')}</p><button data-t="accept">${t('accept')}</button>`;n.querySelector('button').onclick=()=>{localStorage.setItem('sf-cookie','yes');n.remove()};document.body.append(n)}
function initAdmin(){if(!document.body.classList.contains('admin'))return;let data=JSON.parse(localStorage.getItem('sf-products')||'null')||products;const panel=document.querySelector('#admin-panel');const tabs=document.querySelectorAll('[data-admin]');function save(){localStorage.setItem('sf-products',JSON.stringify(data))}function view(which){tabs.forEach(x=>x.classList.toggle('active',x.dataset.admin===which));if(which==='products'){panel.innerHTML=`<div class="admin-panel"><h2>Products <button class="mini" id="add-product">Add product</button></h2><div class="admin-list">${data.map((p,i)=>`<div class="admin-item"><span><b>${p.name}</b><br><small>${p.id} · ${p.type} · ${p.moq}</small></span><span><button class="mini" data-edit="${i}">Edit</button> <button class="mini danger" data-delete="${i}">Delete</button></span></div>`).join('')}</div></div>`;panel.querySelector('#add-product').onclick=()=>edit();panel.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(+b.dataset.edit));panel.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{data.splice(+b.dataset.delete,1);save();view('products')})}else if(which==='enquiries'){const e=JSON.parse(localStorage.getItem('sf-enquiries')||'[]');panel.innerHTML=`<div class="admin-panel"><h2>Enquiries <button class="mini" id="download">Download CSV</button></h2><div class="admin-list">${e.length?e.map(x=>`<div class="admin-item"><span><b>${x.name||'Unnamed contact'}</b><br><small>${x.email||''} · ${x.model||''} · ${x.at||''}</small></span><span>${x.message||''}</span></div>`).join(''):'<p>No browser-local enquiries yet.</p>'}</div></div>`;panel.querySelector('#download')?.addEventListener('click',()=>{const csv=['name,email,company,model,message,date',...e.map(x=>[x.name,x.email,x.company,x.model,(x.message||'').replaceAll(',',' '),x.at].map(v=>`"${v||''}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='veloaxis-enquiries.csv';a.click()})}else{panel.innerHTML='<div class="admin-panel"><h2>Website settings</h2><p>Update public contact details, tracking IDs and share settings when you connect this static site to your own service.</p><label class="field">Google Analytics ID<input placeholder="G-XXXXXXXXXX"></label><button class="btn orange">Save settings</button></div>'}}function edit(i){const p=data[i]||{id:'SF-',name:'',type:'trail',wheel:'29 in',frame:'6061 Alloy',groupset:'1×12 drivetrain',moq:'100 units'};panel.innerHTML=`<div class="admin-panel"><h2>${i===undefined?'Add':'Edit'} product</h2><form id="product-edit"><div class="form-row"><label class="field">Model code<input name="id" value="${p.id}"></label><label class="field">Product name<input name="name" value="${p.name}"></label></div><div class="form-row"><label class="field">Category<select name="type"><option ${p.type==='trail'?'selected':''} value="trail">Trail</option><option ${p.type==='hardtail'?'selected':''} value="hardtail">Hardtail</option><option ${p.type==='electric'?'selected':''} value="electric">E-MTB</option></select></label><label class="field">Wheel<input name="wheel" value="${p.wheel}"></label></div><label class="field">Frame<input name="frame" value="${p.frame}"></label><label class="field">Specification<input name="groupset" value="${p.groupset}"></label><label class="field">MOQ<input name="moq" value="${p.moq}"></label><button class="btn orange">Save product</button></form></div>`;panel.querySelector('form').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));if(i===undefined)data.push(next);else data[i]=next;save();view('products')}}tabs.forEach(b=>b.onclick=()=>view(b.dataset.admin));view('products')}
document.addEventListener('DOMContentLoaded',()=>{const active=document.body.dataset.page||'home';const h=document.querySelector('#site-header'),f=document.querySelector('#site-footer');if(h)h.innerHTML=header(active);if(f)f.innerHTML=footer();setLang(getLang());document.querySelector('#language')?.addEventListener('change',e=>setLang(e.target.value));document.querySelector('#menu')?.addEventListener('click',()=>document.querySelector('#nav').classList.toggle('open'));bindProducts();bindForm();initCookie();initAdmin()});

